15	 */
16	public final class Dtos {
17	
18	    private Dtos() {
19	    }
20	
21	    /** 创建素材请求；id 为空时由系统生成稳定 ID。 */
22	    public record CreateAssetRequest(
23	            String id,
24	            @NotNull @Positive Long durationMs) {
25	    }
26	
27	    /** 素材响应。 */
28	    public record AssetResponse(String id, long durationMs) {
29	    }
30	
31	    /** 创建频道请求；fallbackAssetId 为不会被撤销的保底素材。 */
32	    public record CreateChannelRequest(
33	            String id,
34	            @NotBlank String fallbackAssetId) {
35	    }
36	
37	    /** 频道响应。 */
38	    public record ChannelResponse(String id, String fallbackAssetId) {
39	    }
40	
41	    /** 创建授权请求，有效区间 [validFrom, validTo) 左闭右开。 */
42	    public record CreateGrantRequest(
43	            @NotBlank String channelId,
44	            @NotBlank String assetId,
45	            @NotNull OffsetDateTime validFrom,
46	            @NotNull OffsetDateTime validTo) {
47	    }
48	
49	    /** 授权响应。 */
50	    public record GrantResponse(
51	            long id,
52	            String channelId,
53	            String assetId,
54	            OffsetDateTime validFrom,
55	            OffsetDateTime validTo,
56	            boolean revoked) {
57	    }
58	
59	    /** 撤销授权请求。 */
60	    public record RevokeGrantRequest(@NotBlank String requestId) {
61	    }
62	
63	    /** 草稿片段输入；id 为空时由系统生成。 */
64	    public record SegmentInput(
65	            String id,
66	            @NotBlank String assetId,
67	            @NotNull OffsetDateTime start,
68	            @NotNull OffsetDateTime end) {
69	    }
70	
71	    /** 整份替换草稿请求。 */
72	    public record ReplaceDraftRequest(
73	            @NotBlank String requestId,
74	            @NotNull @PositiveOrZero Long expectedDraftVersion,
75	            @NotNull List<@NotNull SegmentInput> segments) {
76	    }
77	
78	    /** 草稿片段响应。 */
79	    public record SegmentResponse(
80	            String id,
81	            String assetId,
82	            OffsetDateTime start,
83	            OffsetDateTime end) {
84	    }
85	
86	    /** 草稿响应。 */
87	    public record DraftResponse(
88	            String channelId,
89	            String businessDay,
90	            long version,
91	            List<SegmentResponse> segments) {
92	    }
93	
94	    /** 发布请求。 */
95	    public record PublishRequest(
96	            @NotBlank String requestId,
97	            @NotNull @Positive Long draftVersion,
98	            @NotNull @PositiveOrZero Long expectedPublishedVersion) {
99	    }
100	
101	    /** 发布响应。 */
102	    public record PublishResponse(
103	            long publicationId,
104	            String channelId,
105	            String businessDay,
106	            long publishedVersion,
107	            long draftVersion) {
108	    }
109	
110	    /** 播出决定来源：EMERGENCY 命中紧急插播，PROGRAM 命中节目片段，FALLBACK 返回保底素材。 */
111	    public enum DecisionSource {
112	        EMERGENCY, PROGRAM, FALLBACK
113	    }
114	
115	    /** 保底原因：无已发布编排 / 处于空档 / 覆盖片段的授权已撤销。 */
116	    public enum FallbackReason {
117	        NO_PUBLISHED_SCHEDULE, GAP, GRANT_REVOKED
118	    }
119	
120	    /** 播出决定响应；source 为 FALLBACK 时 reason 非空；source 为 EMERGENCY 时 overrideKey 非空。 */
121	    public record PlayoutDecisionResponse(
122	            String channelId,
123	            OffsetDateTime at,
124	            String assetId,
125	            DecisionSource source,
126	            FallbackReason reason,
127	            Long publicationId,
128	            String segmentId,
129	            String overrideKey) {
130	    }
131	
132	    /** 紧急插播状态：创建即 ACTIVE，取消后为 CANCELLED，均为终态语义（ACTIVE 只能转为 CANCELLED）。 */
133	    public enum OverrideStatus {
134	        ACTIVE, CANCELLED
135	    }
136	
137	    /**
138	     * 创建限时紧急插播请求。区间 [start, end) 左闭右开、同处一个 Asia/Shanghai 业务日、
139	     * 时长大于 0 且不超过 30 分钟；priority 取值 1～9；grantId 必须属于该频道与素材并完整覆盖区间。
140	     */
141	    public record CreateEmergencyOverrideRequest(
142	            @NotBlank String requestId,
143	            @NotBlank String overrideKey,
144	            @NotBlank String channelId,
145	            @NotBlank String assetId,
146	            @NotNull @Positive Long grantId,
147	            @NotNull @Min(1) @Max(9) Integer priority,
148	            @NotNull OffsetDateTime start,
149	            @NotNull OffsetDateTime end) {
150	    }
151	
152	    /** 取消紧急插播请求（幂等）。 */
153	    public record CancelEmergencyOverrideRequest(@NotBlank String requestId) {
154	    }
155	
156	    /** 紧急插播明细响应，保存取消情况与原授权关联，不随授权撤销自动换绑。 */
157	    public record EmergencyOverrideResponse(
158	            String overrideKey,
159	            String channelId,
160	            String assetId,
161	            long grantId,
162	            int priority,
163	            OffsetDateTime start,
164	            OffsetDateTime end,
165	            OverrideStatus status,
166	            String cancelRequestId,
167	            OffsetDateTime cancelledAt,
168	            OffsetDateTime createdAt) {
169	    }
170	
171	    /** 统一错误响应体。 */
172	    public record ErrorResponse(String error, String message) {
173	    }
174	}
